function hint(p,text){if(!text)return;const d=el('details',undefined,'translation-hint');d.append(el('summary','Подсказка по-русски'),el('p',text));p.append(d)}
function learnPages(sc){return sc.learnPages||Array.from({length:Math.ceil(sc.learn.length/6)},(_,i)=>sc.learn.slice(i*6,i*6+6))}
function stepKey(){return task().id+':'+state.ex.part+':'+state.ex.round}
function answerText(x){if(x===undefined||x===null)return '';if(typeof x==='string')return x.startsWith('media/')?'Выбранная картинка':fill(x);if(Array.isArray(x))return x.map(answerText).join(' · ');if(typeof x==='object')return Object.entries(x).map(([k,v])=>({'photo':'Фото','caption':'Подпись','color':'Цвет','motifs':'Мотивы'}[k]||k)+': '+answerText(v)).join('; ');return String(x)}
function recordAnswer(value){if(reviewing())return;state.answerLog=state.answerLog||{};const key=stepKey();state.answerLog[key]=state.answerLog[key]||[];state.answerLog[key].push({value:structuredClone(value),correct:null,version:'0.41'});save()}
function expectedAnswer(){const t=part(),r=state.ex.round;if(t.type==='match'){const pair=t.pairs[r%t.pairs.length];return t.direction==='ru'?pair[0]:pair[1]}if(t.type==='quiz')return t.rounds[r].answer;if(t.type==='tokens')return t.pairs[r%t.pairs.length][0];if(t.type==='order')return t.items;if(t.type==='verbTrainer')return t.pairs[r%t.pairs.length][0];if(t.type==='houses')return window.HOUSE_ROUNDS[r].udm;if(t.type==='select')return t.correct||[];if(t.type==='patternBuilder')return ['Кизили','Толэзь','Кизили','Толэзь'];if(t.type==='workshop'&&r===0)return 'Корка';if(t.type==='ballGame')return r%3===0?'Лэзьыны':r%3===1?'Кутыны':['одӥг','кык','куинь','ньыль','вить'][Math.floor(r/3)];if(t.type==='dialogueFill')return(scene().ID==='P19-S03'?[['','Мон шур дуре ветлӥ.'],['','Мон песянаелы юрттӥ.']]:finalDialogue())[r][1];return ''}
function feedback(ok,msg,after){if(reviewing())return;const key=stepKey();state.answerLog=state.answerLog||{};const log=state.answerLog[key]||[];if(log.length)log[log.length-1].correct=ok;const p=$('exerciseFeedback');p.replaceChildren();p.className='feedback '+(ok?'good':'bad');if(ok){p.append(el('p',msg),btn('Продолжить',after,'primary'))}else{state.attempts=state.attempts||{};const n=state.attempts[key]=(state.attempts[key]||0)+1;p.append(el('p',n<3?'Попробуй ещё. Посмотри на вопрос и сравни варианты.':msg));if(n>=3){const correct=expectedAnswer();if(answerText(correct))p.append(el('p','Правильный ответ: '+answerText(correct),'revealed-answer'));if(part().type==='houses')p.append(houseImage(window.HOUSE_ROUNDS[state.ex.round].correct,'Правильный дом'))}}save()}
function objectImage(text){if(/^(Песянай но песятай|Анай но атай|Бабушка и дедушка|Мама и папа)$/i.test(String(text)))return familyPortraits(text);if(String(text).toLowerCase()==='туспуктэм'){const im=el('img');im.src='classic/assets/ch3_vuzhgurt_detail.jpg';im.alt='Туспуктэм';return im}if(String(text).toLowerCase()==='открытка')return el('span','Ӟечбур!','packing-postcard');let key=String(text).trim().toLowerCase().replace(/[.!?]$/,'');key=WORD_ALIASES[key]||key;if(ACTION_MEDIA[key]){const im=el('img',undefined,'choice-image');im.src='media/learning/action_'+ACTION_MEDIA[key]+'__hero_'+(state.gender==='boy'?'b':'g')+'__v01.png';im.alt=key;im.draggable=false;return im}const name=MEDIA_WORDS[key];if(name){const im=el('img',undefined,'choice-image');im.src='media/learning/'+name;im.alt=key;im.draggable=false;return im}if(String(text).includes('Фотография Вужгурта')){const im=el('img');im.src='classic/assets/ch3_vuzhgurt_detail.jpg';im.alt='Вужгурт';return im}if(String(text).includes('Открытка от'))return el('span','Ӟечбур!','packing-postcard');return null}
function answers(p,options,fn,withImages=false){const wrap=el('div',undefined,'answers');for(const o of options){const b=btn(fill(o),()=>{recordAnswer(o);fn(o)});b.dataset.value=o;if(withImages){const im=objectImage(o);if(im)b.prepend(im);if(PATTERNS[o]!==undefined)b.prepend(patternImage(o));}wrap.append(b)}p.append(wrap);return wrap}
function renderMatch(t,p,f){const ps=t.pairs||[];if(!ps.length){p.append(el('p','Слова уже сохранены.'));return}for(const pair of ps)if(!state.learned.includes(pair[0]))state.learned.push(pair[0]);const pair=ps[state.ex.round%ps.length],rev=t.direction==='ru';p.append(el('p',`Шаг ${state.ex.round+1} из ${ps.length}`,'muted'));const image=objectImage(rev?pair[1]:pair[0]);if(image){image.className='question-image';p.append(image)}p.append(el('h2',fill(rev?pair[1]:pair[0])));const correct=rev?pair[0]:pair[1],opts=unique([correct,...shuffle(unique(ps.map(x=>rev?x[0]:x[1])).filter(x=>x!==correct)).slice(0,5),...(t.distractors||[]).slice(0,2)]);answers(p,shuffle(opts),v=>v===correct?roundSuccess(pair,ps.length):feedback(false,'Сравни слово и значение.'));p.append(f);save()}
function housePair(){const wrap=el('div',undefined,'house-distance');const near=el('figure',undefined,'near-house'),far=el('figure',undefined,'far-house');near.append(makeHouse('красный',3),el('figcaption','Татын'));far.append(makeHouse('синий',2),el('figcaption','Отын'));wrap.append(near,far);return wrap}
function tableEvidence(){const table=el('div',undefined,'evidence-table'),card=el('div',undefined,'evidence-postcard');const im=el('img');im.src='classic/assets/ch3_vuzhgurt_detail.jpg';im.alt='Открытка на столе';card.append(im,el('span','Ӟечбур!'));table.append(card);return table}
function renderQuiz(t,p,f){const rs=t.rounds,r=rs[state.ex.round];p.append(el('p',`Шаг ${state.ex.round+1} из ${rs.length}`,'muted'));if(r.evidence==='houses')p.append(housePair());if(r.evidence==='table')p.append(tableEvidence());if(r.evidence==='yard'){const yard=el('div',undefined,'animal-yard');yard.append(el('strong','Милям вань'),objectImage('Пуны'),objectImage('Коӵыш'),objectImage('Скал'),objectImage('Вал'),objectImage('Курег'));p.append(yard)}if(r.image||r.imageByHero){const src=r.imageByHero?.[state.gender]||r.image,im=el('img',undefined,'question-image');im.src=src;im.alt=r.imageAlt||(src.includes('houses')?'Дом':'Картинка к вопросу');p.append(im)}p.append(el('h2',fill(r.prompt)));hint(p,r.hint||t.hint);answers(p,shuffle(r.options),v=>v===r.answer?roundSuccess(v,rs.length):feedback(false,'Сравни вопрос с картинкой.'));p.append(f)}
function renderSelect(t,p,f){let selected=reviewing()?state.responses?.[stepKey()]||[]:[];if(!Array.isArray(selected))selected=[];const wrap=answers(p,t.options,v=>{selected=selected.includes(v)?selected.filter(x=>x!==v):[...selected,v];update()},true);function update(){for(const b of wrap.children)b.classList.toggle('selected',selected.includes(b.dataset.value));preview.replaceChildren();for(const v of selected){const im=objectImage(v);if(im)preview.append(im)}}const preview=el('div',undefined,'selection-preview');p.append(preview,el('p',`Выбери ${t.count}.`,'muted'));hint(p,t.hint);update();p.append(btn('Проверить выбор',()=>{recordAnswer(selected);const ok=selected.length===t.count&&(!t.correct||t.correct.every(x=>selected.includes(x)));if(ok){state.responses[stepKey()]=selected;feedback(true,'Готово!',()=>success(selected));if(t.artifact==='nature')$('exerciseFeedback').append(artifactFigure('nature',selected))}else feedback(false,'Сверь свой выбор с заданием.')},'primary'),f)}
function renderTokens(t,p,f){const pair=t.pairs[state.ex.round%t.pairs.length],target=fill(pair[0]).split(/\s+/),words=[...target,...unique(t.distractors||[]).filter(w=>!target.includes(w)).slice(0,3)];let built=[];if(reviewing()&&typeof state.responses?.[stepKey()]==='string'){const used=new Set;for(const w of state.responses[stepKey()].split(/\s+/)){const i=words.findIndex((x,i)=>x===w&&!used.has(i));if(i>=0){built.push(i);used.add(i)}}}p.append(el('p',`Фраза ${state.ex.round+1} из ${t.pairs.length}`,'muted'),el('h2',fill(pair[1])));const dest=el('div',undefined,'tokens'),src=el('div',undefined,'row token-source');function draw(){dest.replaceChildren();src.replaceChildren();built.forEach((idx,pos)=>dest.append(btn(words[idx],()=>{built.splice(pos,1);draw()})));shuffle(words.map((_,i)=>i)).forEach(idx=>{const b=btn(words[idx],()=>{built.push(idx);draw()});b.disabled=built.includes(idx);src.append(b)})}draw();p.append(dest,src,btn('Проверить фразу',()=>{const answer=built.map(i=>words[i]).join(' ');recordAnswer(answer);if(answer===target.join(' '))roundSuccess(pair[0],t.pairs.length);else feedback(false,'Сравни слова и порядок.')},'primary'),f)}
function renderOrder(t,p,f){let chosen=[];const old=state.responses?.[stepKey()];if(reviewing()&&Array.isArray(old)){const used=new Set;for(const v of old){const i=t.items.findIndex((x,i)=>x===v&&!used.has(i));if(i>=0){chosen.push(i);used.add(i)}}}const dest=el('ol',undefined,'ordered-list'),src=el('div',undefined,'row');function draw(){dest.replaceChildren();src.replaceChildren();chosen.forEach((idx,pos)=>{const li=el('li');li.append(btn(fill(t.items[idx]),()=>{chosen.splice(pos,1);draw()}));dest.append(li)});shuffle(t.items.map((_,i)=>i)).forEach(idx=>{const b=btn(fill(t.items[idx]),()=>{chosen.push(idx);draw()});b.dataset.orderIndex=idx;b.disabled=chosen.includes(idx);if(t.labels?.[idx])b.append(el('small',t.labels[idx],'muted'));src.append(b)})}draw();p.append(dest,src,btn('Проверить порядок',()=>{const values=chosen.map(i=>t.items[i]);recordAnswer(values);const ok=chosen.length===t.items.length&&(t.free||chosen.every((v,i)=>v===i));if(ok){state.responses[stepKey()]=values;feedback(true,'Верно!',()=>success(values))}else feedback(false,'Проверь, что происходит раньше, а что потом.')},'primary'),f)}
function renderHouseMatch(p,f){const r=window.HOUSE_ROUNDS[state.ex.round];p.append(el('p',`Дом ${state.ex.round+1} из 4`,'muted'),el('h2',r.udm));const choices=el('div',undefined,'house-choices');const order=shuffle(r.candidates.slice(state.ex.round%3).concat(r.candidates.slice(0,state.ex.round%3)));for(const src of order){const b=btn('',()=>{recordAnswer(src);if(src===r.correct)roundSuccess(src,4);else feedback(false,'Ещё раз прочитай описание и сравни дома.')},'house-choice');b.dataset.houseKey=src;b.append(houseImage(src,'Вариант дома'));choices.append(b)}p.append(choices,f)}
function renderVerbTrainer(t,p,f){const r=state.ex.round,pair=t.pairs[r%t.pairs.length],parts=pair[0].trim().split(/\s+/),pron=parts.shift(),verb=parts.join(' '),group=t.pairs.slice(Math.floor(r/6)*6,Math.floor(r/6)*6+6),forms=group.map(x=>x[0].trim().split(/\s+/).slice(1).join(' '));let stem=forms[0];for(const form of forms)while(stem&&!form.startsWith(stem))stem=stem.slice(0,-1);const suffix=verb.slice(stem.length),opts=unique(forms.map(x=>x.slice(stem.length)));p.append(el('p',`Шаг ${r+1} из ${t.pairs.length}`,'muted'),el('h2',pron),el('div',stem+' …','verb-stem'));hint(p,pair[1]);const demo=el('details');demo.append(el('summary','Сравнить формы'));for(const [u,ru]of group)demo.append(el('p',u+' — '+ru));p.append(demo);answers(p,shuffle(opts),v=>v===suffix?roundSuccess(pair[0],t.pairs.length):feedback(false,'Посмотри, кто действует, и сравни окончания.'));p.append(f)}
