function renderFamily(p,f){let photo=state.artifacts.selectedPhoto?.value?.[0]||'',caption=state.artifacts.familyDraft?.value?.caption||'';const preview=el('div',undefined,'album-page');function draw(){preview.replaceChildren();if(photo)preview.append(familyPortraits(photo));if(caption)preview.append(el('strong',caption));const pattern=state.artifacts.frame?.value||state.artifacts.pattern?.value?.motifs||['Кизили','Толэзь'];const border=el('div',undefined,'pattern-strip');for(const name of pattern)if(PATTERNS[name]!==undefined)border.append(patternImage(name));const color=state.artifacts.pattern?.value?.color||state.artifacts.frameColor?.value?.[0]||'Горд';preview.style.borderColor=color.startsWith('Лыз')?'#426da7':color.startsWith('Вож')?'#54894c':'#b94337';preview.append(border)}p.append(preview,el('p','Выбери фотографию и подпись.'));answers(p,['Песянай но песятай','Анай но атай'],v=>{photo=v;draw()},true);answers(p,['Анайлэн альбомез','Анаелэн альбомез','Агаедлэн альбомез'],v=>{caption=v;draw()});draw();p.append(btn('Сохранить страницу',()=>{recordAnswer({photo,caption});if(photo&&caption){state.responses[stepKey()]={photo,caption};feedback(true,'Страница готова!',()=>success({photo,caption,pattern:state.artifacts.frame?.value||state.artifacts.pattern?.value?.motifs||['Кизили','Толэзь'],color:state.artifacts.pattern?.value?.color||'Горд'}))}else feedback(false,'Выбери фотографию и подпись.')},'primary'),f)}
function artifactFigure(kind,a){const v=a?.value??a;if(kind==='doll')return dollFigure(v||{});if(kind==='family'||kind==='familyDraft'){const page=el('div',undefined,'album-page');page.append(familyPortraits(v?.photo||'grandparents'));if(v?.caption)page.append(el('strong',v.caption));const border=el('div',undefined,'pattern-strip');for(const name of v?.pattern||[])if(PATTERNS[name]!==undefined)border.append(patternImage(name,v?.color||'Горд'));page.style.borderColor=String(v?.color||'').startsWith('Лыз')?'#426da7':String(v?.color||'').startsWith('Вож')?'#54894c':'#b94337';page.append(border);return page}if(kind==='drawing'&&v?.image){const im=el('img');im.src=v.image;im.alt='Твой рисунок';return im}if(kind==='nature'){const grid=el('div',undefined,'nature-sheet');for(const word of Array.isArray(v)?v:['Куар','Турын','Узы','Губи']){const card=el('figure'),im=objectImage(word);if(im)card.append(im);card.append(el('figcaption',word));grid.append(card)}return grid}if(kind==='pattern'||kind==='frame'){const strip=el('div',undefined,'pattern-strip');for(const word of v?.motifs||v||[])if(PATTERNS[word]!==undefined){const im=patternImage(word);paintPattern(im,v?.color||state.artifacts.pattern?.value?.color||state.artifacts.frameColor?.value?.[0]||'Горд');strip.append(im)}return strip}if(kind==='map'){const map=el('div',undefined,'map-artifact');for(const word of ['корка','шур','корка']){const im=objectImage(word);if(im)map.append(im)}return map}return el('p',answerText(v))}
