function renderWorkshop(p,f){const r=state.ex.round;if(r===0){p.append(el('h2','Мар та?'));const im=objectImage('корка');im.className='question-image';p.append(im);answers(p,['Корка','Шур','Нянь'],v=>v==='Корка'?roundSuccess(v,3):feedback(false,'Рассмотри рисунок.'));p.append(f)}else if(r===1){p.append(el('h2','Нимдэ гожты'));hint(p,'Напиши своё имя');const inp=el('input');inp.setAttribute('aria-label','Имя для рисунка');p.append(inp,btn('Готово',()=>{recordAnswer(inp.value);inp.value.trim()?roundSuccess(inp.value.trim(),3):feedback(false,'Напиши своё имя.')}),f)}else{p.append(el('h2','Нарисуй то, что хочешь показать другу.'));const canvas=el('canvas',undefined,'drawing-pad');canvas.width=600;canvas.height=320;canvas.setAttribute('aria-label','Поле для рисования');const ctx=canvas.getContext?.('2d');let strokes=0,down=false;if(ctx){ctx.lineWidth=5;ctx.lineCap='round';ctx.strokeStyle='#285b43';canvas.onpointerdown=e=>{down=true;strokes++;canvas.setPointerCapture?.(e.pointerId);const r=canvas.getBoundingClientRect();ctx.beginPath();ctx.moveTo((e.clientX-r.left)*600/r.width,(e.clientY-r.top)*320/r.height)};canvas.onpointermove=e=>{if(!down)return;const r=canvas.getBoundingClientRect();ctx.lineTo((e.clientX-r.left)*600/r.width,(e.clientY-r.top)*320/r.height);ctx.stroke()};canvas.onpointerup=()=>down=false;canvas.onpointercancel=()=>down=false}p.append(canvas,btn('Очистить рисунок',()=>{ctx?.clearRect(0,0,600,320);strokes=0}),btn('Сохранить рисунок',()=>{if(!strokes&&ctx){feedback(false,'Сначала нарисуй что-нибудь.');return}const value={image:canvas.toDataURL?.('image/png')||'',name:state.name};recordAnswer('Рисунок сохранён');feedback(true,'Рисунок готов!',()=>success(value))},'primary'),f)}}
function renderPatternBuilder(p,f){let color=state.patternWork?.color||'',motifs=state.patternWork?.motifs||['Кизили','Толэзь'];const preview=el('div',undefined,'pattern-strip');function draw(){preview.replaceChildren();for(const word of motifs){const im=patternImage(word);paintPattern(im,color||'Горд');preview.append(im)}state.patternWork={color,motifs};for(const b of colors.children)b.classList.toggle('selected',b.dataset.value===color);save()}p.append(el('h2','Кыӵе буёлэз быръёд: горд, лыз яке вож?'));const colors=answers(p,['Горд','Лыз','Вож'],v=>{color=v;draw()});p.append(preview,el('p','Кизили, толэзь… Добавь ещё два мотива в том же порядке.'));answers(p,['Кизили','Толэзь','Питыри','Кыз'],v=>{if(motifs.length<4)motifs=[...motifs,v];draw()},true);p.append(btn('Убрать последний мотив',()=>{if(motifs.length>2)motifs=motifs.slice(0,-1);draw()}),btn('Проверить узор',()=>{recordAnswer({color,motifs});if(color&&motifs.join('|')==='Кизили|Толэзь|Кизили|Толэзь'){remember('frameColor',[color]);feedback(true,'Узор готов!',()=>success({color,motifs}))}else feedback(false,'Выбери цвет и повтори: кизили, толэзь, кизили, толэзь.')},'primary'),f);draw()}
