function renderRoutineBoard(p,f){state.routineWork=state.routineWork||{};const work=state.routineWork,source=el('div',undefined,'routine-source'),board=el('div',undefined,'routine-board');let selected='';function assign(word,time){work[word]=time;save();draw()}function draw(){source.replaceChildren();board.replaceChildren();for(const [word]of ROUTINE_ITEMS)if(!work[word]){const b=btn(word,()=>{selected=word;draw()});b.draggable=true;b.ondragstart=e=>e.dataTransfer?.setData('text/plain',word);b.classList.toggle('selected',selected===word);source.append(b)}for(const time of ['Ӵукна','Нунал','Ӝыт','Уй']){const col=el('section',undefined,'routine-column');col.append(el('h3',time),btn('Сюда',()=>{if(selected){assign(selected,time);selected=''}}));col.ondragover=e=>e.preventDefault();col.ondrop=e=>{e.preventDefault();const word=e.dataTransfer?.getData('text/plain');if(ROUTINE_ITEMS.some(x=>x[0]===word))assign(word,time)};for(const [word,t]of Object.entries(work))if(t===time)col.append(btn(word,()=>{delete work[word];draw();save()}));board.append(col)}}draw();p.append(source,board,btn('Сохранить мой день',()=>{recordAnswer(work);if(ROUTINE_ITEMS.every(x=>work[x[0]])){feedback(true,'Твой день сохранён.',()=>success({...work}))}else feedback(false,'Распредели все действия по времени суток.')},'primary'),f)}
function renderHabits(t,p,f){const r=state.ex.round,adv=['котьку','ӵем','куддыръя','шер','ноку'];if(r<5){state.frequencyOrder=state.frequencyOrder||shuffle([0,1,2,3,4]);const index=state.frequencyOrder[r];const scale=el('div',undefined,'frequency');for(let i=0;i<7;i++)scale.append(el('span',undefined,'cell'+(i<[7,5,3,1,0][index]?' filled':'')));p.append(scale);answers(p,adv,v=>v===adv[index]?roundSuccess(v,8):feedback(false,'Посмотри, сколько дней закрашено.'));p.append(f)}else{const verbs=['Султыны','Шудыны','Выдыны'];p.append(el('p','Как часто ты это делаешь? Выбери свой ответ.'),el('h2',verbs[r-5]));answers(p,adv,v=>{state.habitAnswers=state.habitAnswers||[];state.habitAnswers[r-5]=v;remember('habitAnswers',[...state.habitAnswers]);roundSuccess(v,8)});p.append(f)}}
